func New() provisioners.Interface {
	ctx, cancel := context.WithCancel(context.Background())
	return &provisioner{
		ctx:    ctx,
		cancel: cancel,
	}
}

type provisioner struct {
	// We store a context here tied to the lifetime of the provisioner.
	// This allows the Stop method to cancel any in-flight requests.
	ctx    context.Context
	cancel context.CancelFunc
}

func (p *provisioner) GetSchema() (resp provisioners.GetSchemaResponse) {
	schema := &configschema.Block{
		Attributes: map[string]*configschema.Attribute{
			"inline": {
				Type:     cty.List(cty.String),
				Optional: true,
			},
			"script": {
				Type:     cty.String,
				Optional: true,
			},
			"scripts": {
				Type:     cty.List(cty.String),
				Optional: true,
			},
		},
	}

	resp.Provisioner = schema
	return resp
}

func (p *provisioner) ValidateProvisionerConfig(req provisioners.ValidateProvisionerConfigRequest) (resp provisioners.ValidateProvisionerConfigResponse) {
	cfg, err := p.GetSchema().Provisioner.CoerceValue(req.Config)
	if err != nil {
		resp.Diagnostics = resp.Diagnostics.Append(tfdiags.WholeContainingBody(
			tfdiags.Error,
			"Invalid remote-exec provisioner configuration",
			err.Error(),
		))
		return resp
	}

	inline := cfg.GetAttr("inline")
	script := cfg.GetAttr("script")
	scripts := cfg.GetAttr("scripts")

	set := 0
	if !inline.IsNull() {
		set++
	}
	if !script.IsNull() {
		set++
	}
	if !scripts.IsNull() {
		set++
	}
	if set != 1 {
		resp.Diagnostics = resp.Diagnostics.Append(tfdiags.WholeContainingBody(
			tfdiags.Error,
			"Invalid remote-exec provisioner configuration",
			`Only one of "inline", "script", or "scripts" must be set`,
		))
	}
	return resp
}

func (p *provisioner) ProvisionResource(req provisioners.ProvisionResourceRequest) (resp provisioners.ProvisionResourceResponse) {
	if req.Connection.IsNull() {
		resp.Diagnostics = resp.Diagnostics.Append(tfdiags.WholeContainingBody(
			tfdiags.Error,
			"remote-exec provisioner error",
			"Missing connection configuration for provisioner.",
		))
		return resp
	}

	comm, err := communicator.New(req.Connection)
	if err != nil {
		resp.Diagnostics = resp.Diagnostics.Append(tfdiags.WholeContainingBody(
			tfdiags.Error,
			"remote-exec provisioner error",
			err.Error(),
		))
		return resp
	}

	// Collect the scripts
	scripts, err := collectScripts(req.Config)
	if err != nil {
		resp.Diagnostics = resp.Diagnostics.Append(tfdiags.WholeContainingBody(
			tfdiags.Error,
			"remote-exec provisioner error",
			err.Error(),
		))
		return resp
	}
	for _, s := range scripts {
		defer s.Close()
	}

	// Copy and execute each script
	if err := runScripts(p.ctx, req.UIOutput, comm, scripts); err != nil {
		resp.Diagnostics = resp.Diagnostics.Append(tfdiags.WholeContainingBody(
			tfdiags.Error,
			"remote-exec provisioner error",
			err.Error(),
		))
		return resp
	}

	return resp
}

func (p *provisioner) Stop() error {
	p.cancel()
	return nil
}

func (p *provisioner) Close() error {
	return nil
}

// generateScripts takes the configuration and creates a script from each inline config
func generateScripts(inline cty.Value) ([]string, error) {
	var lines []string
	for _, l := range inline.AsValueSlice() {
		if l.IsNull() {
			return nil, errors.New("invalid null string in 'scripts'")
		}

		s := l.AsString()
		if s == "" {
			return nil, errors.New("invalid empty string in 'scripts'")
		}
		lines = append(lines, s)
	}
	lines = append(lines, "")

	return []string{strings.Join(lines, "\n")}, nil
}

// collectScripts is used to collect all the scripts we need
// to execute in preparation for copying them.
func collectScripts(v cty.Value) ([]io.ReadCloser, error) {
	// Check if inline
	if inline := v.GetAttr("inline"); !inline.IsNull() {
		scripts, err := generateScripts(inline)
		if err != nil {
			return nil, err
		}

		var r []io.ReadCloser
		for _, script := range scripts {
			r = append(r, ioutil.NopCloser(bytes.NewReader([]byte(script))))
		}

		return r, nil
	}

	// Collect scripts
	var scripts []string
	if script := v.GetAttr("script"); !script.IsNull() {
		s := script.AsString()
		if s == "" {
			return nil, errors.New("invalid empty string in 'script'")
		}
		scripts = append(scripts, s)
	}

	if scriptList := v.GetAttr("scripts"); !scriptList.IsNull() {
		for _, script := range scriptList.AsValueSlice() {
			if script.IsNull() {
				return nil, errors.New("invalid null string in 'script'")
			}
			s := script.AsString()
			if s == "" {
				return nil, errors.New("invalid empty string in 'script'")
			}
			scripts = append(scripts, s)
		}
	}

	// Open all the scripts
	var fhs []io.ReadCloser
	for _, s := range scripts {
		fh, err := os.Open(s)
		if err != nil {
			for _, fh := range fhs {
				fh.Close()
			}
			return nil, fmt.Errorf("Failed to open script '%s': %v", s, err)
		}
		fhs = append(fhs, fh)
	}

	// Done, return the file handles
	return fhs, nil
}

// runScripts is used to copy and execute a set of scripts
func runScripts(ctx context.Context, o provisioners.UIOutput, comm communicator.Communicator, scripts []io.ReadCloser) error {
	retryCtx, cancel := context.WithTimeout(ctx, comm.Timeout())
	defer cancel()

	type connectResult struct {
		Err error
	}
	var result atomic.Value
	connected := make(chan struct{})
	go func() {
		defer close(connected)

		delay := time.Duration(0)
		for {
			select {
			case <-retryCtx.Done():
				return
			case <-time.After(delay):
			}

			err := comm.Connect(o)
			complete := false
			switch typed := err.(type) {
			case nil:
				complete = true
			case communicator.Fatal:
				err = typed.FatalError()
				complete = true
			}

			result.Store(connectResult{Err: err})
			if complete {
				return
			}

			log.Printf("[WARN] retryable error: %v", err)

			delay *= 2
			if delay == 0 {
				delay = time.Second
			}
			if delay > 20*time.Second {
				delay = 20 * time.Second
			}

			log.Printf("[INFO] sleeping for %s", delay)
		}
	}()

	select {
	case <-retryCtx.Done():
	case <-connected:
	}

	var lastErr error
	if stored, ok := result.Load().(connectResult); ok {
		lastErr = stored.Err
	}

	var err error
	switch retryCtx.Err() {
	case context.Canceled:
		err = fmt.Errorf("interrupted - last error: %v", lastErr)
	case context.DeadlineExceeded:
		err = fmt.Errorf("timeout - last error: %v", lastErr)
	}
	if err == nil {
		err = lastErr
	}

	if err != nil {
		return err
	}

	// Wait for the context to end and then disconnect
	go func() {
		<-ctx.Done()
		comm.Disconnect()
	}()

	for scriptIdx, script := range scripts {
		var cmd *remote.Cmd

		outR, outW := io.Pipe()
		errR, errW := io.Pipe()
		defer outW.Close()
		defer errW.Close()

		go copyUIOutput(o, outR)
		go copyUIOutput(o, errR)

		scriptBytes, readErr := ioutil.ReadAll(script)
		if readErr != nil {
			return fmt.Errorf("Failed to upload script: %v", readErr)
		}

		payload := make([]byte, len(scriptBytes))
		copied := copy(payload, scriptBytes)
		reader := bytes.NewReader(payload)
		unixWrap := strings.TrimSpace(ssh.DefaultShebang)
		summary := fmt.Sprintf("index=%d bytes=%d copied=%d wrap=%q", scriptIdx, len(payload), copied, unixWrap)

		hasShebang := false
		if len(payload) >= 2 {
			if payload[0] == '#' {
				if payload[1] == '!' {
					hasShebang = true
				}
			}
		}

		hasCRLF := false
		blankLines := 0
		lineCount := 0
		lineLen := 0
		maxLine := 0
		printable := 0
		for i := 0; i < len(payload); i++ {
			ch := payload[i]
			printable++
			if ch == '\r' {
				printable--
				hasCRLF = i+1 < len(payload) && payload[i+1] == '\n'
				continue
			}
			if ch == '\n' {
				printable--
				lineCount++
				if lineLen == 0 {
					blankLines++
				}
				if lineLen > maxLine {
					maxLine = lineLen
				}
				lineLen = 0
				continue
			}
			lineLen++
		}
		if lineLen > 0 {
			lineCount++
			if lineLen > maxLine {
				maxLine = lineLen
			}
		}

		summary = fmt.Sprintf("%s shebang=%t crlf=%t lines=%d blank=%d longest=%d printable=%d",
			summary, hasShebang, hasCRLF, lineCount, blankLines, maxLine, printable)
		log.Printf("[DEBUG] remote-exec preparing %s", summary)
		if !hasShebang {
			log.Printf("[DEBUG] remote-exec script %d has no shebang; ssh unix upload would wrap with %q", scriptIdx, unixWrap)
		}

		remotePath := comm.ScriptPath()
		log.Printf("[DEBUG] remote-exec uploading script %d to %s (%d bytes)", scriptIdx, remotePath, reader.Len())
		if err := comm.UploadScript(remotePath, reader); err != nil {
			return fmt.Errorf("Failed to upload script: %v", err)
		}

		cmd = &remote.Cmd{
			Command: remotePath,
			Stdout:  outW,
			Stderr:  errW,
		}
		if err := comm.Start(cmd); err != nil {
			return fmt.Errorf("Error starting script: %v", err)
		}

		if err := cmd.Wait(); err != nil {
			if exitErr, ok := err.(*remote.ExitError); ok {
				if exitErr.Err != nil {
					if exitErr.ExitStatus != 0 {
						if ctx.Err() != nil {
							log.Printf("[WARN] remote command %q failed with status %d after context %v: %v", exitErr.Command, exitErr.ExitStatus, ctx.Err(), exitErr.Err)
						} else {
							log.Printf("[WARN] remote command %q failed with status %d: %v", exitErr.Command, exitErr.ExitStatus, exitErr.Err)
						}
					} else {
						log.Printf("[WARN] remote command %q communicator error: %v", exitErr.Command, exitErr.Err)
					}
					return err
				}
				log.Printf("[WARN] remote command %q exit status %d", exitErr.Command, exitErr.ExitStatus)
			}
			return err
		}

		empty := bytes.NewReader([]byte(""))
		if err := comm.Upload(remotePath, empty); err != nil {
			log.Printf("[WARN] Failed to upload empty follow up script: %v", err)
		}
	}

	return nil
}

func copyUIOutput(o provisioners.UIOutput, r io.Reader) {
	lr := linereader.New(r)
	for line := range lr.Ch {
		o.Output(line)
	}
}

